import {createProductStory} from './product-story.js';
import {useCases,useCaseCategories,useCaseSources} from './usecases-data.js';
const locales = {en:'English',de:'Deutsch',fr:'Français',es:'Español',ro:'Română',hu:'Magyar',bg:'Български'};
const routes=['/','/objects','/measure','/spaces','/uses','/people','/technology','/documentation','/about'];
const routeKeys={'/':'nav.home','/objects':'nav.objects','/measure':'nav.measure','/uses':'nav.uses','/people':'nav.people','/spaces':'nav.spaces','/technology':'nav.technology','/documentation':'nav.documentation','/about':'nav.about'};
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=l=>{l=String(l||'').toLowerCase().split('-')[0];return l==='sp'?'es':Object.hasOwn(locales,l)?l:'en';};
const storage={get:()=>{try{return localStorage.getItem('eva-language');}catch{return null;}},set:v=>{try{localStorage.setItem('eva-language',v);}catch{}}};
let locale=normalize(new URLSearchParams(location.search).get('lang')||storage.get()||navigator.language);
let requestedLocale=locale;
let bundle=null,route=location.pathname.replace(/\/$/,'')||'/',requestId=0,controller=null,menuOpen=false,formatFilter='all',unit='m';
const cache=new Map();
const t=key=>String(bundle?.messages?.[key]??key).replace(/\{\{(\w+)\}\}/g,(_,name)=>String(bundle?.variables?.[name]??''));
const s=key=>h(t(key));
const icon=(name,cls='')=>{const drawings={cube:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 9v9M3 8l9 5 9-5M7.5 5.5l9 5"/>',ruler:'<path d="m4 16 12-12 4 4L8 20l-4-4Zm3-3 2 2m1-5 2 2m1-5 2 2"/>',room:'<path d="M3 21V3h18v18H3Zm10-18v7m0 5v6M3 13h5m5 0h8"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z"/><path d="m8 12 3 3 5-6"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-10 11 10 6 10-6"/>',focus:'<path d="M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 5 6 13 0 18-6-5-6-13 0-18Z"/>'};return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${drawings[name]||drawings.cube}</svg>`;};
const url=p=>`${p}?lang=${locale}`;
const link=(p,key,cls='')=>`<a class="${cls}" data-route="${p}" href="${url(p)}">${s(key)}</a>`;
const badge=()=>`<span class="status-badge"><span aria-hidden="true"></span>${s('status.development')}</span>`;
function header(){return `<a class="skip" href="#main">${s('nav.skip')}</a><header class="site-header"><div class="container header-inner"><a class="brand" data-route="/" href="${url('/')}" aria-label="EVA-3dScan"><img src="/assets/eva-mark-animated.svg" width="40" height="40" alt=""><span><b>EVA<em>-3dScan</em></b><small>iPhone · 3D</small></span></a><nav class="navigation ${menuOpen?'is-open':''}" aria-label="${s('nav.menu')}" id="navigation">${['/objects','/measure','/spaces','/uses','/documentation'].map(p=>`<a data-route="${p}" href="${url(p)}" ${route===p?'aria-current="page"':''}>${s(routeKeys[p])}</a>`).join('')}</nav><div class="header-actions"><label class="language-label">${icon('globe')}<span class="sr-only">${s('nav.language')}</span><select id="language" aria-label="${s('nav.language')}">${Object.entries(locales).map(([code,name])=>`<option value="${code}" ${locale===code?'selected':''}>${name}</option>`).join('')}</select></label><button class="menu-button" id="menu-button" aria-expanded="${menuOpen}" aria-controls="navigation" aria-label="${s(menuOpen?'ui.close':'nav.menu')}">${icon(menuOpen?'close':'menu')}</button></div></div></header>`;}
function footer(){return `<footer><div class="container footer-grid"><div><a class="brand footer-brand" data-route="/" href="${url('/')}"><img src="/assets/eva-mark-animated.svg" width="44" height="44" alt=""><span><b>EVA<em>-3dScan</em></b><small>iPhone · 3D</small></span></a><p>${s('footer.description')}</p>${badge()}</div><div><h3>${s('footer.product')}</h3>${link('/objects','nav.objects')}${link('/measure','nav.measure')}${link('/spaces','nav.spaces')}</div><div><h3>${s('footer.resources')}</h3>${link('/technology','nav.technology')}${link('/documentation','nav.documentation')}${link('/about','nav.about')}${link('/uses','nav.uses')}${link('/people','nav.people')}</div><div><h3>${s('footer.ecosystem')}</h3><a href="https://eva-org.com" target="_blank" rel="noopener noreferrer">EVA</a><a href="https://print.eva-org.com" target="_blank" rel="noopener noreferrer">EVA Print</a><a href="/assets/eva-logo-animated.svg" download="eva-3d-scan-logo.svg">${s('about.brandTitle')}</a></div></div><div class="container language-links" aria-label="${s('nav.language')}">${Object.entries(locales).map(([lang,name])=>`<a data-language="${lang}" href="${route}?lang=${lang}" ${lang===locale?'aria-current="page"':''}>${h(name)}</a>`).join('')}</div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} EVA · ${s('footer.copyright')}</span><span>${s('footer.privacy')}</span></div></footer>`;}
const features=(prefix,count,icons=['focus','ruler','shield','layers'])=>`<div class="feature-grid">${Array.from({length:count},(_,i)=>`<article class="feature">${icon(icons[i%icons.length])}<h3>${s(`${prefix}.feature${i+1}Title`)}</h3><p>${s(`${prefix}.feature${i+1}Text`)}</p></article>`).join('')}</div>`;
const pageHeading=prefix=>`<section class="page-heading container"><div class="eyebrow">${s(`${prefix}.eyebrow`)}</div><h1>${s(`${prefix}.title`)}</h1><p class="lead">${s(`${prefix}.intro`)}</p>${badge()}</section>`;
function home(){return productStory.home();}
const campaignFiles=['06-architect','02-face','07-mario-walls','08-design-couple','09-repair-foreman'];
let campaignSlide=0,carouselPaused=matchMedia('(prefers-reduced-motion: reduce)').matches,carouselTimer=null,carouselHover=false,carouselExplicitPlay=false;
function campaignFrame(){const n=campaignSlide+1;return `<div class="campaign-frame" id="campaign-frame"><img src="/assets/campaign/${campaignFiles[campaignSlide]}.webp" width="1536" height="1024" alt="${s('campaign.slide'+n+'Alt')}" fetchpriority="${campaignSlide===0?'high':'auto'}"><div class="scan-sweep" aria-hidden="true"></div><span class="frame-index">${String(n).padStart(2,'0')} / 05</span>${campaignSlide===1?`<div class="speech-bubble">${s('campaign.speech')}</div>`:''}<div class="slide-caption"><h2>${s('campaign.slide'+n+'Title')}</h2><p>${s('campaign.slide'+n+'Text')}</p></div></div>`;}
function setCampaignSlide(index,{manual=false}={}){campaignSlide=(index+5)%5;if(manual){carouselPaused=true;carouselExplicitPlay=false;}const frame=document.getElementById('campaign-frame');if(!frame)return;frame.outerHTML=campaignFrame();document.querySelectorAll('[data-slide]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===campaignSlide)));const toggle=document.getElementById('carousel-toggle');toggle.textContent=carouselPaused?'▶':'Ⅱ';toggle.setAttribute('aria-label',t(carouselPaused?'campaign.play':'campaign.pause'));if(manual)document.getElementById('announcements').textContent=t('campaign.slide'+(campaignSlide+1)+'Title');scheduleCarousel();}
function scheduleCarousel(){clearTimeout(carouselTimer);if(route!=='/'||carouselPaused||document.hidden||(!carouselExplicitPlay&&(carouselHover||document.getElementById('campaign-carousel')?.contains(document.activeElement))))return;carouselTimer=setTimeout(()=>setCampaignSlide(campaignSlide+1),6500);}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.matches('[data-slide]'))setCampaignSlide(Number(target.dataset.slide),{manual:true});if(target.id==='carousel-prev')setCampaignSlide(campaignSlide-1,{manual:true});if(target.id==='carousel-next')setCampaignSlide(campaignSlide+1,{manual:true});if(target.id==='carousel-toggle'){carouselPaused=!carouselPaused;carouselExplicitPlay=!carouselPaused;target.textContent=carouselPaused?'▶':'Ⅱ';target.setAttribute('aria-label',t(carouselPaused?'campaign.play':'campaign.pause'));scheduleCarousel();}});
document.addEventListener('keydown',event=>{if(!event.target.closest('#campaign-carousel'))return;if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();setCampaignSlide(campaignSlide+(event.key==='ArrowLeft'?-1:1),{manual:true});}});
document.addEventListener('pointerover',event=>{const region=event.target.closest('#campaign-carousel');if(region&&!region.contains(event.relatedTarget)){carouselHover=true;carouselExplicitPlay=false;clearTimeout(carouselTimer);}});
document.addEventListener('pointerout',event=>{const region=event.target.closest('#campaign-carousel');if(region&&!region.contains(event.relatedTarget)){carouselHover=false;scheduleCarousel();}});
document.addEventListener('focusin',event=>{if(event.target.closest('#campaign-carousel')){carouselExplicitPlay=false;clearTimeout(carouselTimer);}});
document.addEventListener('focusout',()=>setTimeout(scheduleCarousel,0));
document.addEventListener('visibilitychange',scheduleCarousel);
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',event=>{if(event.matches){carouselPaused=true;if(route==='/'&&bundle)setCampaignSlide(campaignSlide);}});
function objects(){return `${pageHeading('object')}<section class="container"><figure class="scenario-figure"><img src="/assets/campaign/06-architect.webp" width="1536" height="1024" alt="${s('campaign.slide1Alt')}"><figcaption>${s('status.concept')}</figcaption></figure>${features('object',4)}<p class="note">${s('object.note')}</p></section>${formatsSection(true)}`;}
function measure(){return `${pageHeading('measure')}<section class="container measure-layout"><div class="measurement-demo"><div class="demo-toolbar"><span>${s('measure.demoTitle')}</span><label>${s('measure.unit')}<select id="unit"><option value="m" ${unit==='m'?'selected':''}>m</option><option value="cm" ${unit==='cm'?'selected':''}>cm</option><option value="mm" ${unit==='mm'?'selected':''}>mm</option></select></label></div><div class="measurement-grid"><svg viewBox="0 0 600 360" aria-hidden="true"><path class="demo-plane" d="M95 95h410v165H95z"/><path class="demo-frame" d="M95 95h410v165H95zM95 75v-25m410 25v-25M95 60h410"/><path class="demo-marks" d="m95 60 9-5v10Zm410 0-9-5v10Z"/><circle cx="95" cy="95" r="5"/><circle cx="505" cy="95" r="5"/><path class="demo-corners" d="M80 110V80h30m380 0h30v30m0 135v30h-30m-380 0H80v-30"/></svg><output id="measurement-value" class="measurement-value">${measurementValue()}</output><span class="measurement-label">${s('measure.demoLabel')}</span></div><p>${s('measure.demoNote')}</p></div><div class="measure-features"><figure class="scenario-figure measure-portrait"><img src="/assets/campaign/07-mario-walls.webp" width="1536" height="1024" alt="${s('campaign.slide3Alt')}"><figcaption>${s('status.concept')}</figcaption></figure>${features('measure',3,['shield','ruler','layers'])}</div></section>`;}
function measurementValue(){const value=unit==='mm'?1240:unit==='cm'?124:1.24;return new Intl.NumberFormat(locale,{maximumFractionDigits:2}).format(value)+' '+unit;}
function spaces(){return `${pageHeading('spaces')}<section class="container"><div class="room-scenarios">${[['08-design-couple','design'],['09-repair-foreman','repair']].map(([file,key])=>`<article class="room-scenario"><img src="/assets/campaign/${file}.webp" width="1536" height="1024" alt="${s('spaces.'+key+'Alt')}"><div><h2>${s('spaces.'+key+'Title')}</h2><p>${s('spaces.'+key+'Text')}</p></div></article>`).join('')}</div>${features('spaces',3,['room','layers','ruler'])}<p class="note">${s('spaces.note')}</p></section>`;}
const formats=[['STL','print','planned'],['3MF','print','planned'],['PLY','cloud','planned'],['USDZ','view','planned'],['DXF','cad','planned'],['OBJ','view','planned'],['GLB / glTF','view','planned'],['E57','cloud','conditional'],['LAS / LAZ','cloud','conditional'],['XYZ / PCD','cloud','planned'],['DWG','cad','conditional'],['IFC / STEP','cad','conditional']];
function formatsSection(compact=false){const selected=formats.filter(f=>formatFilter==='all'||f[1]===formatFilter);return `<section class="container section format-section"><div class="section-heading"><div><div class="eyebrow">CAD · 3D PRINT · POINT CLOUD</div><h2>${s('tech.formatsTitle')}</h2></div><p>${s('tech.formatsIntro')}</p></div><div class="format-filters" role="group" aria-label="${s('tech.formatsTitle')}">${['all','print','cloud','cad','view'].map(f=>`<button data-filter="${f}" aria-pressed="${f===formatFilter}" class="filter ${f===formatFilter?'selected':''}">${s('tech.filter'+f[0].toUpperCase()+f.slice(1))}</button>`).join('')}</div><div class="format-grid">${selected.map(([name,type,status])=>`<div class="format-card"><strong>${name}</strong><span>${s('tech.'+status)}</span></div>`).join('')}</div><p class="format-note">${s('tech.formatNote')}</p>${compact?link('/technology','nav.technology','text-link'):''}</section>`;}
function technology(){return `${pageHeading('tech')}<section class="container tech-grid">${[['capture','layers'],['scale','ruler'],['privacy','shield']].map(([k,ic])=>`<article class="tech-card">${icon(ic)}<h2>${s('tech.'+k+'Title')}</h2><p>${s('tech.'+k+'Text')}</p></article>`).join('')}</section>${formatsSection()}`;}
function documentation(){return `${pageHeading('docs')}<section class="container documentation-layout"><div class="document-cover"><span>EVA<br>3D SCAN</span><div class="cover-lines"></div><small>RESEARCH & DESIGN</small><b>01 / 2026</b></div><div class="document-description"><div class="eyebrow">${s('docs.pdfMeta')}</div><h2>${s('docs.researchTitle')}</h2><p>${s('docs.researchText')}</p><a class="button primary" href="/downloads/EVA-3D-Scan-dossier-ro.pdf" target="_blank" rel="noopener">${icon('download')}${s('docs.download')}</a><h3>${s('docs.methodTitle')}</h3><p>${s('docs.methodText')}</p></div></section><section class="container section"><div class="section-heading"><div><div class="eyebrow">STL · PLY · DXF</div><h2>${s('docs.sampleTitle')}</h2></div><p>${s('docs.sampleText')}</p></div><div class="sample-grid">${[['cube-100mm.stl','cube','docs.sampleCube','100 × 100 × 100 mm'],['reference-cloud.ply','focus','docs.sampleCloud','PLY · XYZ + RGB'],['room-4x3m.dxf','room','docs.sampleRoom','4 × 3 m']].map(([file,ic,key,meta])=>`<a class="sample" href="/downloads/${file}" download>${icon(ic)}<h3>${s(key)}</h3><span>${meta}</span>${icon('download')}</a>`).join('')}</div></section><section class="container sources-section"><h2>${s('docs.sourcesTitle')}</h2><a href="https://developer.apple.com/documentation/realitykit/realitykit-object-capture" target="_blank" rel="noopener noreferrer">${s('docs.appleLink')}${icon('plus')}</a><a href="https://developer.apple.com/augmented-reality/roomplan/" target="_blank" rel="noopener noreferrer">${s('docs.roomplanLink')}${icon('plus')}</a><a href="https://www.nist.gov/document/tn1297spdf" target="_blank" rel="noopener noreferrer">${s('docs.nistLink')}${icon('plus')}</a></section>`;}
function about(){return `${pageHeading('about')}<section class="container about-grid"><article class="brand-panel"><img src="/assets/eva-logo-animated.svg" width="290" height="68" alt="EVA-3dScan"><h2>${s('about.brandTitle')}</h2><p>${s('about.brandText')}</p><a class="button secondary" href="/assets/eva-logo-animated.svg" download>${icon('download')}${s('ui.download')}</a></article><article><h2>${s('about.statusTitle')}</h2><p>${s('about.statusText')}</p>${link('/documentation','nav.documentation','button secondary')}<h3>${s('about.ecosystem')}</h3><div class="ecosystem-links"><a href="https://eva-org.com" target="_blank" rel="noopener noreferrer">${s('about.evaLink')}</a><a href="https://print.eva-org.com" target="_blank" rel="noopener noreferrer">${s('about.printLink')}</a></div></article></section>`;}
function render({keepScroll=true}={}){const y=scrollY;const region=document.getElementById('campaign-carousel');const active=document.activeElement;const initialHydration=document.getElementById('app').dataset.ssr==='true';const useFocused=active?.id==='use-search';const useSelection=useFocused?[active.selectionStart,active.selectionEnd]:null;const focused=region?.contains(active);const storyFocus=['customer-profile','customer-problem'].includes(active?.id)?'#'+active.id:active?.hasAttribute('data-faq')?'[data-faq="'+active.dataset.faq+'"]':active?.hasAttribute('data-demo')?'[data-demo="'+active.dataset.demo+'"]':active?.hasAttribute('data-profession')?'[data-profession="'+active.dataset.profession+'"]':null;const focusSelector=storyFocus|| (useFocused?'#use-search':focused?(active.id?'#'+active.id:active.hasAttribute('data-slide')?'[data-slide="'+active.dataset.slide+'"]':null):null);if(region&&(carouselHover||region.matches(':hover')||focused))carouselPaused=true;const pages={'/':home,'/objects':objects,'/measure':measure,'/spaces':spaces,'/uses':uses,'/people':people,'/technology':technology,'/documentation':documentation,'/about':about};document.documentElement.lang=locale;document.title=(route==='/'?'':t(routeKeys[route]||'ui.notFound')+' · ')+t('meta.title');updatePageMetadata();document.getElementById('app').innerHTML=header()+`<main id="main" tabindex="-1">${pages[route]?pages[route]():`<section class="container page-heading"><h1>${s('ui.notFound')}</h1><p>${s('ui.notFoundText')}</p>${link('/','nav.home','button primary')}</section>`}</main>`+footer();document.getElementById('app').removeAttribute('data-ssr');if(keepScroll)window.scrollTo(0,y);carouselHover=false,carouselExplicitPlay=false;if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true});if(useSelection)document.getElementById('use-search')?.setSelectionRange(...useSelection);if(initialHydration&&location.hash){try{const id=decodeURIComponent(location.hash.slice(1));document.getElementById(id)?.scrollIntoView({block:'start',behavior:'instant'});}catch{}}scheduleCarousel();}
async function loadLanguage(next,{force=false}={}){next=normalize(next);requestedLocale=next;const id=++requestId;controller?.abort();controller=new AbortController();const old=locale;try{let data=cache.get(next);if(!data||force){const response=await fetch('/api/content?lang='+next,{signal:controller.signal,cache:'no-cache'});if(!response.ok)throw Error('Content '+response.status);data=await response.json();if(!data.messages||typeof data.messages!=='object')throw Error('Invalid content');cache.set(next,data);}if(id!==requestId)return;bundle=data;locale=next;storage.set(locale);const address=new URL(location.href);address.searchParams.set('lang',locale);history.replaceState({},'',address);render();document.getElementById('announcements').textContent=t('ui.updated');}catch(error){if(error.name==='AbortError')return;console.error('Content unavailable',error.message);if(bundle){locale=old;render();document.getElementById('announcements').textContent=t('ui.error');}else if(document.getElementById('app')?.dataset.ssr==='true'){document.getElementById('announcements').textContent='Content refresh unavailable';}else{const fallback={en:['Content is temporarily unavailable.','Try again'],ro:['Conținutul este temporar indisponibil.','Reîncearcă'],de:['Der Inhalt ist vorübergehend nicht verfügbar.','Erneut versuchen'],fr:['Le contenu est temporairement indisponible.','Réessayer'],es:['El contenido no está disponible temporalmente.','Reintentar'],hu:['A tartalom átmenetileg nem érhető el.','Újrapróbálkozás'],bg:['Съдържанието временно не е достъпно.','Опитайте отново']}[next];document.getElementById('app').innerHTML=`<div class="initial error-state"><img src="/assets/eva-mark-animated.svg" width="52" height="52" alt="EVA"><h1>${h(fallback[0])}</h1><button class="button primary" id="retry">${h(fallback[1])}</button></div>`;}}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-route]');if(a&&e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();if(a.dataset.useCategory){useCategory=a.dataset.useCategory;useSearch='';}route=a.dataset.route;menuOpen=false;history.pushState({},'',url(route));render({keepScroll:false});window.scrollTo({top:0,behavior:'instant'});document.getElementById('main').focus({preventScroll:true});return;}const filter=e.target.closest('[data-filter]');if(filter){formatFilter=filter.dataset.filter;render();document.querySelector(`[data-filter="${formatFilter}"]`)?.focus({preventScroll:true});}if(e.target.closest('#menu-button')){menuOpen=!menuOpen;render();document.getElementById('menu-button')?.focus();}if(e.target.closest('#retry'))loadLanguage(locale,{force:true});});
document.addEventListener('change',e=>{if(e.target.id==='language')loadLanguage(e.target.value);if(e.target.id==='unit'){unit=e.target.value;document.getElementById('measurement-value').textContent=measurementValue();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuOpen){menuOpen=false;render();document.getElementById('menu-button')?.focus();}});
window.addEventListener('popstate',()=>{route=location.pathname.replace(/\/$/,'')||'/';const wanted=normalize(new URLSearchParams(location.search).get('lang')||locale);loadLanguage(wanted);});
const events=new EventSource('/api/events');events.addEventListener('content',()=>{cache.clear();loadLanguage(requestedLocale,{force:true});});
window.addEventListener('online',()=>loadLanguage(requestedLocale,{force:true}));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')loadLanguage(requestedLocale,{force:true});});
let useCategory='all',useSearch='';
const categoryIcon={objects_print:'cube',measure_diy:'ruler',interior_design:'focus',repair_construction:'shield',spaces_property:'room',people_creative:'layers'};
function homeUses(){return `<section class="container home-uses"><div class="section-heading"><div><div class="eyebrow">${s('uses.homeLabel')}</div><h2>${s('uses.homeTitle')}</h2></div><p>${s('uses.homeText')}</p></div><div class="use-category-grid">${useCaseCategories.map(cat=>`<a class="use-category-card" href="${url('/uses')}" data-route="/uses" data-use-category="${cat}">${icon(categoryIcon[cat])}<h3>${s('uses.category.'+cat)}</h3><span aria-hidden="true">↗</span></a>`).join('')}</div><div class="person-link"><p>${s('people.homeText')}</p>${link('/people','people.homeLink','text-link')}</div></section>`;}
function uses(){return `${pageHeading('uses')}<section class="container"><div class="uses-tools"><label class="uses-search" for="use-search">${s('uses.searchLabel')}<input id="use-search" type="search" value="${h(useSearch)}" placeholder="${s('uses.searchPlaceholder')}" autocomplete="off"></label><div class="uses-filters" role="group" aria-label="${s('uses.filterLabel')}">${['all',...useCaseCategories].map(cat=>`<button data-use-filter="${cat}" aria-pressed="${cat===useCategory}">${s(cat==='all'?'uses.all':'uses.category.'+cat)}</button>`).join('')}</div></div><div id="uses-results">${usesResults()}</div><p class="uses-method">${s('uses.method')}</p></section><section class="container uses-sources"><h2>${s('uses.sourcesTitle')}</h2><p>${s('uses.sourcesIntro')}</p><div class="uses-source-links">${useCaseSources.map(source=>`<a href="${h(source.url)}" target="_blank" rel="noopener noreferrer">${h(source.label)} ↗</a>`).join('')}</div></section>`;}
function usesResults(){const query=useSearch.toLocaleLowerCase(locale).normalize('NFD').replace(/\p{Diacritic}/gu,'');const results=useCases.filter(item=>(useCategory==='all'||item.category===useCategory)&&(!query||[t('usecase.'+item.id+'.title'),t('usecase.'+item.id+'.description'),t('usecase.'+item.id+'.keywords')].join(' ').toLocaleLowerCase(locale).normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(query)));return `<p class="uses-count" role="status"><strong>${results.length}</strong>${s('uses.results')}</p><div class="usecase-grid">${results.map(item=>`<article class="usecase-card" id="usecase-${item.id}"><span class="usecase-category">${s('uses.category.'+item.category)}</span><h2>${s('usecase.'+item.id+'.title')}</h2><p>${s('usecase.'+item.id+'.description')}</p><div class="usecase-keywords">${t('usecase.'+item.id+'.keywords').split('|').map(term=>`<span>${h(term.trim())}</span>`).join('')}</div>${link(item.module,'uses.openModule','text-link')}</article>`).join('')}</div>${results.length?'':`<p class="uses-empty">${s('uses.noResults')}</p>`}`;}
function refreshUses(){const target=document.getElementById('uses-results');if(target)target.innerHTML=usesResults();document.querySelectorAll('[data-use-filter]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.useFilter===useCategory)));}
function people(){return `${pageHeading('people')}<section class="container people-layout"><figure class="scenario-figure"><img src="/assets/campaign/02-face.webp" width="1536" height="1024" alt="${s('campaign.slide2Alt')}"><figcaption>${s('campaign.speech')} · ${s('status.concept')}</figcaption></figure>${features('people',3,['focus','cube','shield'])}</section><section class="container"><p class="note">${s('people.note')}</p>${link('/uses','uses.homeLink','button secondary')}</section>`;}
function updatePageMetadata(){const prefix={'/':'hero','/objects':'object','/measure':'measure','/spaces':'spaces','/uses':'uses','/people':'people','/technology':'tech','/documentation':'docs','/about':'about'}[route]||'hero';const raw=key=>bundle?.messages?.[key]?t(key):'';const title=raw(prefix+'.metaTitle')||(route==='/'?t('meta.title'):t(prefix+'.title')+' · '+bundle.variables.product);const description=raw(prefix+'.metaDescription')||(route==='/'?(raw('campaign.heroIntro')||raw('hero.description')||raw('meta.description')):(raw(prefix+'.intro')||raw('meta.description')));document.title=title;document.querySelector('meta[name="description"]').content=description;const canonical=document.getElementById('seo-canonical');const origin=canonical?new URL(canonical.href).origin:'https://3dscan.eva-org.com';const address=origin+route+'?lang='+locale;if(canonical)canonical.href=address;for(const lang of [...Object.keys(locales),'x-default']){const alternate=document.getElementById('seo-alternate-'+lang);if(alternate)alternate.href=origin+route+'?lang='+(lang==='x-default'?'en':lang);}for(const [property,value] of Object.entries({'og:title':title,'og:description':description,'og:url':address,'og:locale':locale})){const meta=document.querySelector(`meta[property="${property}"]`);if(meta)meta.content=value;}for(const [name,value] of Object.entries({'twitter:title':title,'twitter:description':description})){const meta=document.querySelector(`meta[name="${name}"]`);if(meta)meta.content=value;}const data=document.getElementById('seo-jsonld');if(data)data.textContent=JSON.stringify({'@context':'https://schema.org','@type':'SoftwareApplication','@id':origin+'/#software',name:bundle.variables.product,applicationCategory:'UtilitiesApplication',operatingSystem:'iOS',inLanguage:locale,creativeWorkStatus:t('status.development'),description:description+' '+t('status.development'),url:origin+'/?lang='+locale});}
document.addEventListener('input',event=>{if(event.target.id==='use-search'){useSearch=event.target.value;refreshUses();}});
document.addEventListener('click',event=>{const filter=event.target.closest('[data-use-filter]');if(filter){useCategory=filter.dataset.useFilter;refreshUses();}});

document.addEventListener('click',event=>{const a=event.target.closest('[data-language]');if(a&&event.button===0&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey){event.preventDefault();loadLanguage(a.dataset.language);}});
const productStory=createProductStory({s,t,h,icon,url,link,badge,campaignFrame,getSlide:()=>campaignSlide,isPaused:()=>carouselPaused});
loadLanguage(locale);
